user_prompt:
method derivative(xs: seq<int>) returns (result: seq<int>)
    requires xs.Length > 0
    ensures result.Length == xs.Length - 1
    ensures forall i :: 0 <= i < result.Length ==> result[i] == xs[i + 1] * (i + 1)
{
    var n := xs.Length;
    var res := new int[n - 1];
    for i := 0 to n - 2 {
        res[i] := xs[i + 1] * (i + 1);
    }
    result := res;
}
